import {openingLesson} from './lesson-one.js';
import {lessonMetadata} from './curriculum.js';
import {caseLessons} from './course-cases.js';
import {questionEvidence} from './course-evidence.js';
export const chapters=[{title:'The local network',subtitle:'From an application to the first hop'},{title:'Beyond your router',subtitle:'Configuration, routes and addressing'},{title:'Delivery & discovery',subtitle:'Connections, reliability and names'},{title:'Trust & the web',subtitle:'From a DNS answer to an HTTP response'},{title:'The modern Internet',subtitle:'Streams, sessions and intermediaries'},{title:'Investigate & reason',subtitle:'Read evidence and understand failures'}];
export const lessons=[{...openingLesson,reworked:2},...lessonMetadata.map(meta=>{
 const rewritten=caseLessons[meta.id];
 if(!rewritten)throw new Error('Missing concrete lesson: '+meta.id);
 return {...meta,...rewritten};
})];
lessons.forEach((lesson,index)=>{
 lesson.index=index;lesson.chapter=Math.floor(index/4);lesson.minutes=10;
 lesson.questions.forEach((question,i)=>{
  question.id=`${lesson.id}-${i+1}`;question.lessonId=lesson.id;
  if(questionEvidence[lesson.id])question.givens=questionEvidence[lesson.id][i];
 });
});
export const questions=lessons.flatMap(lesson=>lesson.questions);
export const glossary={
'protocol':'An agreement defining message formats, meaning and expected behavior.',
'packet':'A network-layer unit, such as an IP header and payload, carried over local links.',
'frame':'A link-layer envelope for delivery across a local link.',
'encapsulation':'Wrapping one protocol’s data inside another protocol’s envelope.',
'MAC address':'A link-layer address for local delivery, not cryptographic identity.',
'switch':'A device forwarding local frames using learned link-address locations.',
'broadcast':'Delivery throughout a relevant broadcast domain; ordinary routers stop Ethernet broadcasts.',
'access point':'A device connecting Wi-Fi clients to a network, commonly bridging wireless and wired links.',
'IPv4':'Internet Protocol version 4, using 32-bit addresses.',
'prefix':'Leading address bits defining a network or routing range; /24 means 24 specified bits.',
'subnet':'An address subdivision identified by a prefix and relevant network configuration.',
'default gateway':'The next-hop router used by an applicable default route when no more specific route wins.',
'ARP':'Address Resolution Protocol: learns an on-link IPv4 neighbor’s link address.',
'neighbor cache':'Stored local-neighbor information including IP-to-link-address mappings and state.',
'next hop':'The immediate neighbor selected for forwarding a packet toward its destination.',
'DHCP':'Dynamic Host Configuration Protocol: supplies leases and options such as routers and resolvers.',
'lease':'Time-limited permission to use a supplied address, subject to renewal rules.',
'resolver':'Software or a service that obtains DNS answers for a client.',
'route':'A destination-range forwarding entry specifying a next hop, interface or other action.',
'longest prefix match':'Selecting the matching forwarding prefix with the most specified leading bits.',
'TTL':'DNS: ordinary cache lifetime in seconds. IP: forwarding hop limit. Context determines meaning.',
'MTU':'Maximum Transmission Unit: largest IP packet supported by a link without relevant adaptation.',
'ICMP':'Internet Control Message Protocol: diagnostic and error feedback, including echo and Time Exceeded.',
'NAT':'Network Address Translation: rewrites addresses; port translation can let flows share a public IPv4 address.',
'port':'A transport endpoint number. A number alone does not verify the service or its safety.',
'flow':'Related traffic grouped by protocol and endpoint information such as addresses and ports.',
'private address':'An address in a range reserved for private networking rather than ordinary global routing.',
'IPv6':'Internet Protocol version 6, using 128-bit addresses and mechanisms such as Neighbor Discovery.',
'Neighbor Discovery':'ICMPv6 mechanisms for local neighbors and routers, including link-address resolution.',
'SLAAC':'Stateless Address Autoconfiguration: forming IPv6 addresses using advertised prefixes and host behavior.',
'link-local':'Address scope limited to one link; important for IPv6 neighbor and router communication.',
'TCP':'Transmission Control Protocol: an ordered byte stream with connection state, loss recovery and flow/congestion controls.',
'socket':'An operating-system communication endpoint exposed through an application API.',
'handshake':'An exchange establishing protocol state or parameters; authentication depends on the protocol.',
'sequence number':'A position in TCP sequence space used for ordering bytes and control events.',
'acknowledgement':'Receipt feedback under protocol rules; a cumulative TCP ACK names the next contiguous byte expected.',
'flow control':'Restricting transmission according to the receiver’s available capacity.',
'congestion control':'Adjusting sending according to conditions along the network path.',
'UDP':'User Datagram Protocol: port-addressed datagrams without built-in ordering or retransmission.',
'datagram':'A discrete message unit. UDP retains delivered datagram boundaries rather than exposing a byte stream.',
'retransmission':'Sending data again after suspected loss; higher protocols may add it above UDP.',
'QUIC':'A secure UDP-carried transport with connections, reliable streams and congestion control.',
'DNS':'Domain Name System: a distributed name database with records, delegation and caches.',
'recursive resolver':'A DNS service obtaining answers for clients using caches and other DNS servers.',
'authoritative server':'A DNS server publishing authoritative data for a zone.',
'NXDOMAIN':'A DNS response code saying the queried domain name does not exist.',
'DNSSEC':'DNS Security Extensions: supports validation of signed data, not query confidentiality.',
'DoH':'DNS over HTTPS: protected client-to-resolver transport using HTTPS.',
'DoT':'DNS over TLS: protected client-to-resolver transport using TLS.',
'TLS':'Transport Layer Security: communication protection and configured peer authentication.',
'certificate':'Signed public-key and identity information, subject to validation and trust rules.',
'certificate authority':'An issuer in a certificate system; trust chains lead toward accepted trust anchors.',
'hostname':'A name used to identify a service context; the intended name matters in HTTPS validation.',
'key exchange':'A method for deriving shared secret material; authentication is a related separate requirement.',
'session key':'Secret key material for a protected session. Modern TLS derives separate traffic secrets and keys.',
'SNI':'Server Name Indication: TLS handshake information selecting the intended service; visibility depends on encrypted client hello.',
'TLS termination':'The endpoint where a TLS connection is decrypted and processed.',
'HTTP':'Hypertext Transfer Protocol: request/response semantics carried through different wire versions.',
'method':'An HTTP operation such as GET or POST with defined request semantics.',
'status code':'An HTTP numeric response indicator interpreted in the request context.',
'cache validator':'Metadata such as an ETag used to conditionally check a stored representation.',
'multiplexing':'Interleaving multiple logical exchanges over shared infrastructure.',
'HTTP/2':'A framed, multiplexed HTTP mapping commonly used over TLS and TCP.',
'HTTP/3':'HTTP mapped onto QUIC, using UDP as the underlying carrier.',
'cookie':'Browser-stored state sent under HTTP cookie scope and security rules.',
'session':'Application state linking interactions, commonly recognized through a token.',
'origin':'For ordinary web URLs, scheme, host and port used in browser security boundaries.',
'SameSite':'Cookie attribute affecting cross-site sending. A site is distinct from an origin.',
'CDN':'Content Delivery Network: distributed serving infrastructure, often with caching and proxying.',
'reverse proxy':'An intermediary accepting requests and forwarding selected work to upstream services.',
'load balancer':'A service distributing work among eligible backends.',
'origin server':'The source service behind an intermediary such as a CDN.',
'firewall':'Traffic policy enforcement using rules and observed context.',
'stateful filtering':'Filtering informed by tracked flow or connection state.',
'VPN':'Virtual Private Network: tunneled connectivity, commonly authenticated and encrypted.',
'tunnel':'Carrying inner communication inside another protocol between chosen endpoints.',
'capture point':'The interface or location from which traffic evidence is collected.',
'display filter':'A tool expression limiting displayed recorded packets without changing the recorded capture.',
'timeline':'An ordered account of observations with timestamps and bounded conclusions.',
'spoofing':'Presenting a false source or identity claim.',
'ARP poisoning':'Introducing misleading local IPv4-to-link-address mappings.',
'DNS poisoning':'Introducing unwanted name-related data into resolution or caches.',
'authentication':'Verifying identity or origin under a defined method and trust model.',
'DDoS':'Distributed Denial of Service: disruption using multiple sources or infrastructure.',
'amplification':'A small input producing a larger response or disproportionate resource cost.',
'rate limiting':'Restricting traffic or work over time under a defined grouping policy.',
'bottleneck':'The resource limiting useful throughput or availability under current conditions.',
'dependency':'A prerequisite another operation relies on, such as a route for a DNS query.',
'evidence':'An observation supporting a bounded conclusion, distinct from a proposed explanation.',
'hypothesis':'A proposed explanation that can be tested against alternatives.',
'return path':'The route and policy for responder-to-sender traffic; it can differ from the forward path.'
};
